// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Private_Bank} from "../src/Private_Bank.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Private_Bank c;

    function setUp() public {
        c = new Private_Bank(address(this));
    }

    function _test(address depositor, uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmount == c.MinDeposit());
        vm.assume(address(this).balance >= depositAmount);
        bool reverted = false;
        uint256 balanceBefore;
        try c.balances(depositor) returns (uint256 __r) { balanceBefore = __r; } catch { return; }
        try c.Deposit{value: depositAmount}() { } catch { reverted = true; }
        uint256 balanceAfter;
        try c.balances(depositor) returns (uint256 __r) { balanceAfter = __r; } catch { return; }
        assertTrue(balanceAfter == balanceBefore);
    }

    function testFuzz_test(address depositor, uint256 depositAmount) public {
        _test(depositor, depositAmount);
    }

    receive() external payable {}
}
